+    /// Get a string representation of this table with trailing whitespace removed from each line.
+    ///
+    /// This is useful for borderless tables, where trailing whitespace would otherwise
+    /// appear at the end of each line.
+    ///
+    /// ```
+    /// use comfy_table::{Table, presets::ASCII_NO_BORDERS};
+    ///
+    /// let mut table = Table::new();
+    /// table.set_header(&vec!["Header1", "Header2", "Header3"]);
+    /// table.add_row(&vec!["One", "Two", "Three"]);
+    /// table.load_preset(ASCII_NO_BORDERS);
+    ///
+    /// // Using `to_string()` would include trailing whitespace:
+    /// // " Header1 | Header2 | Header3   \n"
+    /// //
+    /// // Using `trim_fmt()` removes trailing whitespace:
+    /// // " Header1 | Header2 | Header3\n"
+    /// let trimmed = table.trim_fmt();
+    /// assert_eq!(trimmed, " Header1 | Header2 | Header3\n=============================\n One     | Two     | Three");
+    /// ```
+    pub fn trim_fmt(&self) -> String {
+        let display_info = arrange_content(self);
+        let content = format_content(&self, &display_info);
+        let lines = draw_borders(&self, content, &display_info);
+
+        // Trim trailing whitespace from each line
+        let trimmed_lines: Vec<&str> = lines.iter().map(|line| line.trim_end()).collect();
+        trimmed_lines.join("\n")
+    }
