+
+/// Implementation of a Tokenizer which does not have tokenization state.
+///
+/// This is a wrapper which is generic over dictionary pointers.
+/// Usable where dictionary is a struct itself, &, &mut, Rc<.>, Arc<.>.
+pub struct StatelessTokenizer<T> {
+    dict: T,
+}
+
+impl<T> StatelessTokenizer<T>
+where
+    T: Deref,
+    <T as Deref>::Target: DictionaryAccess,
+{
+    /// Creates a new StatelessTokenizer
+    ///
+    /// # Arguments
+    /// * `dict` - A dictionary implementing `DictionaryAccess`
+    ///
+    /// # Returns
+    /// A new `StatelessTokenizer` instance
+    pub fn new(dict: T) -> StatelessTokenizer<T> {
+        StatelessTokenizer { dict }
+    }
+
+    /// Creates a new StatelessTokenizer with a dictionary and configuration
+    ///
+    /// This is the preferred constructor when you have both a dictionary and
+    /// configuration available. The configuration provides tokenizer settings
+    /// such as OOV providers and path rewrite plugins.
+    ///
+    /// # Arguments
+    /// * `dict` - A shared reference-counted pointer to a `JapaneseDictionary`
+    /// * `config` - Reference to a `Config` object containing tokenizer settings
+    ///
+    /// # Returns
