+    pub fn new_with_config(dict: T, _config: &Config) -> StatelessTokenizer<T> {
+        StatelessTokenizer { dict }
+    }
+
+    /// Returns a reference to the underlying dictionary
+    pub fn as_dict(&self) -> &<T as Deref>::Target {
