+
+    fn auth(
+        object: &mut PrimitiveObject,
+        args: &HashMap<String, Literal>,
+        data: &mut Data,
+        interval: Interval,
+        _content_type: &str,
+    ) -> Result<Literal, ErrorInfo> {
+        let usage = "auth(username: string, password: string) => http object";
+
+        if args.len() != 2 {
+            return Err(gen_error_info(
+                Position::new(interval, &data.context.flow,),
+                format!("usage: {}", usage),
+            ));
+        }
+
+        let username = match args.get("arg0") {
+            Some(literal) => Literal::get_value::<String>(
+                &literal.primitive,
+                &data.context.flow,
+                interval,
+                "auth username should be a string".to_owned(),
+            )?,
+            _ => {
+                return Err(gen_error_info(
+                    Position::new(interval, &data.context.flow,),
+                    format!("usage: {}", usage),
+                ))
+            }
+        };
+
+        let password = match args.get("arg1") {
+            Some(literal) => Literal::get_value::<String>(
+                &literal.primitive,
+                &data.context.flow,
+                interval,
+                "auth password should be a string".to_owned(),
+            )?,
+            _ => {
+                return Err(gen_error_info(
+                    Position::new(interval, &data.context.flow,),
+                    format!("usage: {}", usage),
+                ))
+            }
+        };
+
+        // Build the Basic auth header: "Basic <base64(username:password)>"
+        let credentials = format!("{}:{}", username, password);
+        let encoded = base64::encode(credentials.as_bytes());
+        let auth_header = format!("Basic {}", encoded);
+
+        let mut object = object.to_owned();
+
+        // Get or create the header map
+        let header = object.value.entry("header".to_owned()).or_insert_with(|| {
+            PrimitiveObject::get_literal(&HashMap::new(), interval)
+        });
+
+        // Insert the Authorization header
+        if let Ok(header_map) = Literal::get_mut_value::<HashMap<String, Literal>>(
+            &mut header.primitive,
+            &data.context.flow,
+            interval,
+            ERROR_HTTP_SET.to_owned(),
+        ) {
+            header_map.insert(
+                "Authorization".to_owned(),
+                PrimitiveString::get_literal(&auth_header, interval),
+            );
+        } else {
+            return Err(gen_error_info(
+                Position::new(interval, &data.context.flow,),
+                "Failed to set authorization header".to_owned(),
+            ));
+        }
+
+        let mut result = PrimitiveObject::get_literal(&object.value, interval);
+
+        result.set_content_type("http");
+
+        Ok(result)
+    }
 }

