+        // If we've collected all elements, iterate from the vector
+        if self.next.is_none() {
+            let total_consumed = self.front_consumed + self.back_consumed;
+            if self.front_consumed < self.v.len() - self.back_consumed {
+                let item = self.v[self.front_consumed];
+                self.front_consumed += 1;
+                return Some(item);
+            }
+            return None;
+        }
+        
+        // Otherwise, continue forward iteration through the chain
         let next = self.next?;
+        self.v.push(next);
         self.next = next.source();
+        self.front_consumed += 1;
         Some(next)
     }
+
+    fn size_hint(&self) -> (usize, Option<usize>) {
+        let len = self.len();
+        (len, Some(len))
+    }
