+    fn next_back(&mut self) -> Option<Self::Item> {
+        // Collect all remaining elements if not already done
+        if self.next.is_some() {
+            while let Some(error) = self.next.take() {
+                self.v.push(error);
+                self.next = error.source();
+            }
+        }
+        
+        // Return elements from the back of the vector
+        let total_consumed = self.front_consumed + self.back_consumed;
+        if total_consumed < self.v.len() {
+            self.back_consumed += 1;
+            Some(self.v[self.v.len() - self.back_consumed])
+        } else {
+            None
+        }
+    }
+}
+
+impl<'a> ExactSizeIterator for Chain<'a> {
+    fn len(&self) -> usize {
+        // Count buffered elements that haven't been consumed yet
+        let buffered_remaining = self.v.len().saturating_sub(self.front_consumed + self.back_consumed);
+        
+        // Count unbuffered elements still in the chain
+        let mut count = buffered_remaining;
+        let mut current = self.next;
+        while let Some(error) = current {
+            count += 1;
+            current = error.source();
+        }
+        count
+    }
 }
