diff --git a/src/serde_bin.rs b/src/serde_bin.rs
index d82d6b6..988348b 100644
--- a/src/serde_bin.rs
+++ b/src/serde_bin.rs
@@ -402,14 +402,82 @@ where
     T: DeBin,
 {
     fn de_bin(o: &mut usize, d: &[u8]) -> Result<Self, DeBinErr> {
-        unsafe {
-            let mut to = core::mem::MaybeUninit::<[T; N]>::uninit();
-            let top: *mut T = core::mem::transmute(&mut to);
-            for c in 0..N {
-                top.add(c).write(DeBin::de_bin(o, d)?);
+        // Deserialize each element into individual variables first.
+        // This ensures that if deserialization fails partway through,
+        // already-deserialized elements are properly dropped.
+        
+        // Use a tuple to hold each element as an independent variable
+        struct ArrayBuilder<T, const N: usize> {
+            arr: [core::mem::MaybeUninit<T>; N],
+            initialized: usize,
+        }
+        
+        impl<T, const N: usize> ArrayBuilder<T, N> {
+            fn new() -> Self {
+                Self {
+                    arr: [const { core::mem::MaybeUninit::uninit() }; N],
+                    initialized: 0,
+                }
+            }
+            
+            fn push(&mut self, value: T) {
+                // SAFETY: We're only calling this with sequential indices starting from 0
+                unsafe {
+                    self.arr.get_unchecked_mut(self.initialized).write(value);
+                }
+                self.initialized += 1;
+            }
+            
+            // Drop all initialized elements
+            fn drop_initialized(&mut self) {
+                // Drop in reverse order
+                while self.initialized > 0 {
+                    self.initialized -= 1;
+                    // SAFETY: This index has been initialized.
+                    // We need to get a pointer to the inner T and drop it,
+                    // because drop_in_place on &mut MaybeUninit<T> won't call T's Drop.
+                    unsafe {
+                        core::ptr::drop_in_place(self.arr[self.initialized].as_mut_ptr());
+                    }
+                }
+            }
+        }
+        
+        // Manually implement Drop for ArrayBuilder to ensure cleanup
+        impl<T, const N: usize> Drop for ArrayBuilder<T, N> {
+            fn drop(&mut self) {
+                self.drop_initialized();
             }
-            Ok(to.assume_init())
         }
+        
+        // Use a macro to create the array and handle cleanup
+        macro_rules! build_array {
+            ($o:expr, $d:expr) => {{
+                let mut builder = ArrayBuilder::<T, N>::new();
+                
+                // Try to deserialize each element
+                for i in 0..N {
+                    match DeBin::de_bin($o, $d) {
+                        Ok(value) => builder.push(value),
+                        Err(e) => {
+                            // Drop already-initialized elements before returning error
+                            builder.drop_initialized();
+                            return Err(e);
+                        }
+                    }
+                }
+                
+                // All elements are successfully deserialized.
+                // Prevent builder's Drop from dropping the elements by
+                // setting initialized to 0 (they'll be moved to the result).
+                builder.initialized = 0;
+                
+                // SAFETY: All elements have been initialized
+                Ok(unsafe { core::mem::transmute_copy(&builder.arr) })
+            }};
+        }
+        
+        build_array!(o, d)
     }
 }

