+    /// Converts a string to camelCase in a way that's compatible with serde's `rename_all = "camelCase"`.
+    /// The key difference from the Inflector crate is that we split by underscore/hyphen first,
+    /// then lowercase the first character of the first part, while capitalizing the first character
+    /// of each subsequent part. This produces `crc32cHash` instead of `crc32CHash` for `crc32c_hash`.
+    fn to_camel_case(string: &str) -> String {
+        let parts: Vec<&str> = string.split(|c: char| c == '_' || c == '-').collect();
+        if parts.is_empty() {
+            return string.to_lowercase();
+        }
+
+        let mut result = parts[0].to_lowercase();
+        for part in &parts[1..] {
+            if !part.is_empty() {
+                let mut chars = part.chars();
+                if let Some(first) = chars.next() {
+                    result.push(first.to_ascii_uppercase());
+                    result.extend(chars);
+                }
+            }
+        }
+        result
+    }
+
+    /// Converts a string to PascalCase in a way that's compatible with serde's `rename_all = "PascalCase"`.
+    fn to_pascal_case(string: &str) -> String {
+        let parts: Vec<&str> = string.split(|c: char| c == '_' || c == '-').collect();
+        let mut result = String::new();
+        for part in parts {
+            if !part.is_empty() {
+                let mut chars = part.chars();
+                if let Some(first) = chars.next() {
+                    result.push(first.to_ascii_uppercase());
+                    result.extend(chars);
+                }
+            }
         }
+        result
+    }
+
+    fn to_snake_case(string: &str) -> String {
+        let mut result = String::new();
+        for (i, c) in string.chars().enumerate() {
+            if i > 0 && c.is_uppercase() {
+                result.push('_');
+            }
+            result.push(c.to_ascii_lowercase());
+        }
+        // Handle consecutive uppercase letters (e.g., "HTTPServer" -> "http_server")
+        // by inserting underscore before each uppercase letter that's followed by a lowercase
+        let mut final_result = String::new();
+        let chars: Vec<char> = result.chars().collect();
+        for i in 0..chars.len() {
+            if i > 0 
+                && chars[i].is_uppercase() 
+                && i + 1 < chars.len() 
+                && chars[i + 1].is_ascii_lowercase() 
+                && chars[i - 1] != '_' 
+            {
+                final_result.push('_');
+            }
+            final_result.push(chars[i]);
+        }
+        final_result.replace("__", "_")
+    }
+
+    fn to_screaming_snake_case(string: &str) -> String {
+        Self::to_snake_case(string).to_uppercase()
+    }
+
+    fn to_kebab_case(string: &str) -> String {
+        Self::to_snake_case(string).replace('_', "-")
     }
 }

