+/// Reinterprets a mutable slice as a mutable slice of `MaybeUninit` elements.
+///
+/// This function allows zero-cost conversion from `&mut [T]` to
+/// `&mut [MaybeUninit<T>]`, enabling APIs that operate on uninitialized
+/// buffers (like `getrandom_inner`) to be used without unnecessary zero-filling.
+///
+/// # Safety
+///
+/// The caller must ensure that the returned slice is fully initialized
+/// before it is read as the original type `T`. Until then, the slice must
+/// not be accessed as `T`.
+pub fn slice_as_uninit_mut<T>(slice: &mut [T]) -> &mut [MaybeUninit<T>] {
+    // SAFETY: MaybeUninit<T> has the same layout as T, and we return a &mut
+    // which gives exclusive access. The caller is responsible for ensuring
+    // proper initialization before reading as T.
+    unsafe { &mut *(slice as *mut [T] as *mut [MaybeUninit<T>]) }
+}

