+    /// Removes all objects from the pool that don't satisfy the predicate.
+    ///
+    /// This can be used to implement max-lifetime and idle-lifetime policies.
+    /// The predicate receives a reference to the managed object and its
+    /// metrics, and returns `true` to keep the object or `false` to drop it.
+    ///
+    /// This operation blocks the pool while the predicate runs.
+    pub fn retain<F>(&self, f: F)
+    where
+        F: Fn(&M::Type, &Metrics) -> bool,
+    {
+        if self.inner.semaphore.is_closed() {
+            return;
+        }
+        let mut slots = self.inner.slots.lock().unwrap();
+        let mut to_remove = Vec::new();
+        // Iterate through all objects and identify which ones to remove
+        for (idx, inner) in slots.vec.iter().enumerate() {
+            if !f(&inner.obj, &inner.metrics) {
+                to_remove.push(idx);
+            }
+        }
+        // Remove objects from the back to avoid index shifting issues
+        // The objects we remove are idle in the pool, so we need to:
+        // 1. Decrement the size counter
+        // 2. Decrement the available counter (these were available objects)
+        // 3. Detach to notify the manager
+        for &idx in to_remove.iter().rev() {
+            if let Some(mut inner) = slots.vec.remove(idx) {
+                slots.size -= 1;
+                drop(slots);
+                let _ = self.inner.available.fetch_sub(1, Ordering::Relaxed);
+                self.inner.manager.detach(&mut inner.obj);
+                slots = self.inner.slots.lock().unwrap();
+            }
+        }
+    }
