+package secp256k1
+
+import (
+        "crypto/sha512"
+        "fmt"
+
+        "github.com/btcsuite/btcd/btcec"
+
+        sdkSignature "github.com/oasisprotocol/oasis-sdk/client-sdk/go/crypto/signature"
+)
+
+// Signer is a Secp256k1 signer.
+type Signer struct {
+        privateKey *btcec.PrivateKey
+        publicKey  PublicKey
+}
+
+// Public returns the public key corresponding to the signer.
+func (s *Signer) Public() sdkSignature.PublicKey {
+        if s == nil || s.publicKey == nil {
+                return nil
+        }
+        return s.publicKey
+}
+
+// ContextSign generates a signature with the private key over the context and message.
+func (s *Signer) ContextSign(context, message []byte) ([]byte, error) {
+        if s == nil || s.privateKey == nil {
+                return nil, fmt.Errorf("signer is reset")
+        }
+
+        // Compute the hash to sign.
+        hash := PrepareSignerMessage(context, message)
+
+        // Sign the hash.
+        sig, err := s.privateKey.Sign(hash)
+        if err != nil {
+                return nil, err
+        }
+
+        return sig.Serialize(), nil
+}
+
+// String returns the string representation of the signer.
+func (s *Signer) String() string {
+        if s == nil {
+                return ""
+        }
+        return s.publicKey.String()
+}
+
+// Reset tears down the signer and obliterates any sensitive state.
+func (s *Signer) Reset() {
+        if s == nil || s.privateKey == nil {
+                return
+        }
+        // Zero out the private key.
+        for i := range s.privateKey.D.Bytes() {
+                s.privateKey.D.Bytes()[i] = 0
+        }
+        s.privateKey = nil
+        s.publicKey = nil
+}
+
+// PrepareSignerMessage prepares the message to be signed by computing
+// SHA-512/256 over the concatenation of context and message.
+func PrepareSignerMessage(context []byte, message []byte) []byte {
+        h := sha512.New512_256()
+        h.Write(context)
+        h.Write(message)
+        return h.Sum(nil)
+}
