diff --git a/crates/trippy-tui/src/frontend/render/info_bar.rs b/crates/trippy-tui/src/frontend/render/info_bar.rs
new file mode 100644
index 0000000..3b19eba
--- /dev/null
+++ b/crates/trippy-tui/src/frontend/render/info_bar.rs
@@ -0,0 +1,55 @@
+use crate::frontend::tui_app::TuiApp;
+use crate::t;
+use ratatui::layout::Rect;
+use ratatui::style::{Modifier, Style};
+use ratatui::text::{Line, Span};
+use ratatui::widgets::{Block, Borders, Paragraph};
+use ratatui::Frame;
+use trippy_dns::ResolveMethod;
+
+/// Render the info bar at the bottom of the TUI.
+pub fn render(f: &mut Frame<'_>, rect: Rect, app: &TuiApp) {
+    let details = if app.show_hop_details {
+        String::from(t!("on"))
+    } else {
+        String::from(t!("off"))
+    };
+    let as_info = match app.resolver.config().resolve_method {
+        ResolveMethod::System => String::from(t!("na")),
+        ResolveMethod::Resolv | ResolveMethod::Google | ResolveMethod::Cloudflare => {
+            if app.tui_config.lookup_as_info {
+                String::from(t!("on"))
+            } else {
+                String::from(t!("off"))
+            }
+        }
+    };
+    let max_hosts = app
+        .tui_config
+        .max_addrs
+        .map_or_else(|| String::from(t!("auto")), |m| m.to_string());
+    let privacy = app.tui_config.privacy_max_ttl;
+    let info_line = Line::from(vec![
+        Span::styled(
+            format!("{}={} ", t!("as-info"), as_info),
+            Style::default().add_modifier(Modifier::BOLD),
+        ),
+        Span::raw(format!(
+            "{}={} {}={} {}={}",
+            t!("details"),
+            details,
+            t!("max-hosts"),
+            max_hosts,
+            t!("privacy"),
+            privacy
+        )),
+    ]);
+    let info_bar = Paragraph::new(info_line)
+        .style(
+            Style::default()
+                .bg(app.tui_config.theme.info_bar_bg)
+                .fg(app.tui_config.theme.info_bar_text),
+        )
+        .block(Block::default().borders(Borders::NONE));
+    f.render_widget(info_bar, rect);
+}
