@@ -16,6 +16,72 @@ use tokio::task::JoinSet;
 use tokio::time::Instant;
 use tracing::{error, instrument};

+/// Resolves the namespace roots for a `Tasks` instance.
+/// It first trims each supplied root, validates that it is not an empty or
+/// otherwise malformed namespace, then attempts an exact name match. If no
+/// exact match is found, it treats the root as a namespace prefix (adding a
+/// trailing colon if needed) and returns all tasks whose names start with
+/// that prefix. Invalid or non‑matching roots cause a `TaskNotFound` error.
+fn resolve_namespace_roots(
+    roots: &[String],
+    task_indices: &HashMap<String, NodeIndex>,
+) -> Result<Vec<NodeIndex>, Error> {
+    let mut result = Vec::new();
+
+    for name in roots {
+        // Step 1: Trim whitespace
+        let trimmed = name.trim();
+
+        // Step 2: Validate the root
+        // - Empty after trimming
+        if trimmed.is_empty() {
+            return Err(Error::TaskNotFound(name.clone()));
+        }
+        // - Contains only a colon
+        if trimmed == ":" {
+            return Err(Error::TaskNotFound(name.clone()));
+        }
+        // - Starts with a colon
+        if trimmed.starts_with(':') {
+            return Err(Error::TaskNotFound(name.clone()));
+        }
+        // - Contains a double-colon ("::")
+        if trimmed.contains("::") {
+            return Err(Error::TaskNotFound(name.clone()));
+        }
+
+        // Step 3: Check for exact match first
+        if let Some(index) = task_indices.get(trimmed) {
+            result.push(*index);
+            continue;
+        }
+
+        // Step 4: Check if this is a namespace prefix
+        // Add a trailing colon if not present, then find all tasks with that prefix
+        let prefix = if trimmed.ends_with(':') {
+            trimmed.to_string()
+        } else {
+            format!("{}:", trimmed)
+        };
+
+        let matching_tasks: Vec<_> = task_indices
+            .iter()
+            .filter(|(task_name, _)| task_name.starts_with(&prefix))
+            .map(|(_, &index)| index)
+            .collect();
+
+        if !matching_tasks.is_empty() {
+            result.extend(matching_tasks);
+            continue;
+        }
+
+        // No match found - return error
+        return Err(Error::TaskNotFound(name.clone()));
+    }
+
+    Ok(result)
+}
