+        let lifetime = u64::strict_decode(&mut d)?;
+        let addendum = SweepAddressAddendum::strict_decode(&mut d)?;
+        // Decode from_height as Option<u64>
+        let flag = u8::strict_decode(&mut d)?;
+        let from_height = if flag == 1 {
+            Some(u64::strict_decode(&mut d)?)
+        } else {
+            None
+        };
+        Ok(Self {
+            id,
+            lifetime,
+            addendum,
+            from_height,
+        })
+    }
