+use proc_macro2::{TokenStream, TokenTree, Literal};
+
+fn main() {
+    println!("=== Testing negative integer literals ===\n");
+    
+    // Test various negative integer types
+    test_literal("i8", Literal::i8_suffixed(-42i8));
+    test_literal("i16", Literal::i16_suffixed(-42i16));
+    test_literal("i32", Literal::i32_suffixed(-42i32));
+    test_literal("i64", Literal::i64_suffixed(-42i64));
+    test_literal("i128", Literal::i128_suffixed(-42i128));
+    test_literal("isize", Literal::isize_suffixed(-42isize));
+    
+    // Test unsuffixed
+    test_literal("i8_unsuffixed", Literal::i8_unsuffixed(-42i8));
+    test_literal("i32_unsuffixed", Literal::i32_unsuffixed(-42i32));
+    
+    // Test hex/octal/binary
+    test_literal("-0x2A (hex)", Literal::i32_suffixed(-42i32));
+    
+    // Test that positive literals are NOT split
+    println!("\n=== Testing positive integer literals (should NOT be split) ===\n");
+    test_literal("positive i32", Literal::i32_suffixed(42i32));
+    test_literal("positive u32", Literal::u32_suffixed(42u32));
+    
+    // Test floats (should NOT be split according to rustc behavior)
+    println!("\n=== Testing float literals (should NOT be split) ===\n");
+    test_literal("negative f32", Literal::f32_suffixed(-42.0f32));
+    test_literal("negative f64", Literal::f64_suffixed(-42.0f64));
+}
+
+fn test_literal(name: &str, lit: Literal) {
+    let mut tokens = TokenStream::new();
+    tokens.extend(std::iter::once(TokenTree::Literal(lit)));
+    
+    let token_vec: Vec<_> = tokens.into_iter().collect();
+    print!("{:25}: {} token(s) - ", name, token_vec.len());
+    
+    for (i, tt) in token_vec.iter().enumerate() {
+        if i > 0 {
+            print!(" + ");
+        }
+        match tt {
+            TokenTree::Literal(l) => print!("{}", l),
+            TokenTree::Punct(p) => print!("'{}'", p.as_char()),
+            _ => print!("{:?}", tt),
+        }
+    }
+    println!();
+}
