+use std::iter;
+use proc_macro2::{TokenStream, TokenTree, Literal};
+
+fn main() {
+    // Test with fallback disabled (uses compiler's implementation if available)
+    println!("=== Without forcing fallback ===");
+    test_negative_literals();
+    
+    // Force fallback mode
+    println!("\n=== With fallback forced ===");
+    proc_macro2::fallback::force();
+    test_negative_literals();
+}
+
+fn test_negative_literals() {
+    let int: i32 = -3;
+    let lit = Literal::i32_suffixed(int);
+    
+    let mut tokens = TokenStream::new();
+    tokens.extend(iter::once(TokenTree::Literal(lit)));
+    
+    let token_vec: Vec<_> = tokens.clone().into_iter().collect();
+    println!("Number of tokens: {}", token_vec.len());
+    for (i, tt) in token_vec.iter().enumerate() {
+        match tt {
+            TokenTree::Literal(lit) => println!("  [{}] Literal: {}", i, lit),
+            TokenTree::Punct(punct) => println!("  [{}] Punct: '{}' (spacing: {:?})", i, punct.as_char(), punct.spacing()),
+            TokenTree::Ident(ident) => println!("  [{}] Ident: {}", i, ident),
+            TokenTree::Group(_group) => println!("  [{}] Group", i),
+        }
+    }
+    
+    println!("Debug output: {:?}", tokens);
+}
