+/// Check if a literal string represents a negative integer literal (not float).
+/// This matches rustc's behavior where only integer literals starting with '-'
+/// are split into two tokens. Float literals are NOT split.
+fn is_negative_integer_literal(s: &str) -> bool {
+    // Must start with minus sign
+    if !s.starts_with('-') {
+        return false;
+    }
+    
+    let s = &s[1..]; // Skip the minus sign
+    
+    // Skip any leading underscores (though they're not valid, we handle them gracefully)
+    let s = s.trim_start_matches('_');
+    
+    if s.is_empty() {
+        return false;
+    }
+    
+    // Check if it contains a decimal point - if so, it's a float
+    if s.contains('.') {
+        return false;
+    }
+    
+    // Check if it has an exponent part (e.g., 1e10, 1E10)
+    // We need to be careful not to match the 'e' in suffixes like "isize"
+    if let Some(pos) = s.find('e').or_else(|| s.find('E')) {
+        // Check if it's actually an exponent (followed by optional +/- and digits)
+        let after_e = &s[pos + 1..];
+        if after_e.chars().next().map_or(false, |c| c == '+' || c == '-' || c.is_ascii_digit()) {
+            return false;
+        }
+    }
+    
+    // Check if it ends with an f suffix (f32 or f64)
+    if s.ends_with("f32") || s.ends_with("f64") {
+        return false;
+    }
+    
+    // Check if it starts with a digit or 0x/0o/0b prefix
+    let mut chars = s.chars();
+    match chars.next() {
+        Some('0') => {
+            // Could be 0x, 0o, 0b, or just 0
+            match chars.next() {
+                Some('x' | 'X' | 'o' | 'O' | 'b' | 'B') => {
+                    // Hex/octal/binary - check that remaining chars are valid for that base
+                    // For simplicity, just check that there's at least one more character
+                    chars.next().is_some()
+                }
+                _ => {
+                    // Just 0 or 0 followed by digits
+                    true
+                }
+            }
+        }
+        Some(c) if c.is_ascii_digit() => {
+            // Decimal number
+            true
+        }
+        _ => false,
+    }
+}
